from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
import json, pathlib, urllib.request
PAGE=pathlib.Path(__file__).with_name('index.html').read_bytes()
OPENER=urllib.request.build_opener(urllib.request.ProxyHandler({}))
class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path not in ('/','/index.html'):
            self.send_error(404); return
        self.send_response(200); self.send_header('Content-Type','text/html; charset=utf-8'); self.send_header('Content-Length',str(len(PAGE))); self.end_headers(); self.wfile.write(PAGE)
    def do_POST(self):
        if self.path!='/chat': self.send_error(404); return
        origin=self.headers.get('Origin')
        if origin and origin not in ('http://127.0.0.1:8765','http://localhost:8765'):
            self.send_error(403); return
        try:
            length=int(self.headers.get('Content-Length','0'))
            if not 0<length<=200000: raise ValueError('输入过长或为空')
            data=json.loads(self.rfile.read(length))
            messages=data['messages']
            if not isinstance(messages,list) or not messages: raise ValueError('无效的对话')
            for m in messages:
                if m.get('role') not in ('user','assistant') or not isinstance(m.get('content'),str): raise ValueError('无效消息')
            messages=[dict(m) for m in messages[-16:]]
            payload={'model':'qwen3:4b-instruct','messages':[{'role':'system','content':'你是一位实用的中文助手。默认用中文简洁回答；不了解的事情请明确说明。'}]+messages[-16:],'stream':True,'think':False,'keep_alive':'1m','options':{'num_ctx':4096,'num_predict':2048}}
            req=urllib.request.Request('http://127.0.0.1:11434/api/chat',data=json.dumps(payload).encode(),headers={'Content-Type':'application/json'})
            upstream=OPENER.open(req,timeout=180)
        except Exception as exc:
            self.send_error(502,str(exc)); return
        self.send_response(200); self.send_header('Content-Type','application/x-ndjson'); self.send_header('Connection','close'); self.end_headers(); self.close_connection=True
        try:
            with upstream:
                for line in upstream:
                    self.wfile.write(line); self.wfile.flush()
        except (BrokenPipeError,ConnectionResetError): pass
        except Exception:
            try: self.wfile.write(b'{"error":"Local model connection interrupted"}\n'); self.wfile.flush()
            except OSError: pass
ThreadingHTTPServer(('127.0.0.1',8765),Handler).serve_forever()
